message.content:
{
  "title": "The Mirror's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver surfaces in a ruined courtyard.",
      "visual_description": "A cracked courtyard with fallen royal banners, the glass diver climbing out of a shattered window frame, helmet glinting.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer consults a map of the city.",
      "visual_description": "Mara unrolls a stained map on a broken fountain, compass in hand, studying the path ahead.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning from a doorway.",
      "visual_description": "An old stone doorway, the oracle lamp hanging from a rusted hook, its single eye flaring.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector snores behind a pile of rubble.",
      "visual_description": "A half-collapsed wall, the sleeping tax collector curled on a stack of ledgers, papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scampers ahead to scout the castle gates.",
      "visual_description": "Rusty iron castle gates, the tin fox darting between fallen stones, key-wind tail twitching.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The glass diver peers through a cursed tower window.",
      "visual_description": "A spiraling tower with dark vines, the glass diver pressing his helmet against a frosted pane.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Mara marks a safe route past the tower.",
      "visual_description": "Mara crouches behind a broken statue, inking a new line on her map, compass dangling.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp warns of a trap ahead.",
      "visual_description": "A narrow alley with scattered bones, the oracle lamp glowing red from a ledge.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector stirs but does not wake.",
      "visual_description": "A collapsed market stall, the sleeping tax collector shifts, mumbling, papers rustling.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox finds a hidden passage behind a magic door.",
      "visual_description": "A shimmering magic door set in a wall, the tin fox nudging it open with its snout.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The glass diver swims through a mirror into a locked room.",
      "visual_description": "A dusty chamber with a large mirror, the glass diver emerging like from water, helmet dripping light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara deciphers a coded message on the wall.",
      "visual_description": "A wall covered in faded runes, Mara tracing them with an ink-stained finger, compass set aside.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp guides them past an armored patrol.",
      "visual_description": "A wide street, empty armor suits standing in formation, the oracle lamp dimming its light.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector is accidentally rolled onto a stretcher.",
      "visual_description": "A makeshift stretcher of old banners, the sleeping tax collector snoring, papers trailing behind.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "The tin fox triggers a false alarm to distract patrols.",
      "visual_description": "A clattering of loose stones, the tin fox racing away as armored figures turn.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver opens the final gate from inside.",
      "visual_description": "A heavy portcullis, the glass diver reaching through its bars to lift the latch from the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "Mara leads the group across the crumbling bridge.",
      "visual_description": "A stone bridge over a chasm, missing stones, Mara at the front, map in hand, the others following.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they escape.",
      "visual_description": "The far side of the bridge, the span falling into darkness, the group safe on solid ground.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ],
  "title": "The Mirror's Escape"
}

